#!/usr/bin/env python3
"""TokenGuard - API Cost Guardian"""
import os
import sys
import json
from datetime import datetime, date
from pathlib import Path

TOKENGUARD_DIR = Path(os.environ.get('TOKENGUARD_DIR', '~/.tokenguard')).expanduser()
DEFAULT_LIMIT = float(os.environ.get('TOKENGUARD_DEFAULT_LIMIT', '20.0'))
WARNING_PCT = float(os.environ.get('TOKENGUARD_WARNING_PCT', '0.8'))

def ensure_dir():
    TOKENGUARD_DIR.mkdir(parents=True, exist_ok=True)

def load_limit():
    limit_file = TOKENGUARD_DIR / 'limit.json'
    if limit_file.exists():
        return json.loads(limit_file.read_text())
    return {'limit': DEFAULT_LIMIT, 'currency': 'USD'}

def save_limit(data):
    ensure_dir()
    (TOKENGUARD_DIR / 'limit.json').write_text(json.dumps(data, indent=2))

def load_session():
    session_file = TOKENGUARD_DIR / 'session.json'
    if session_file.exists():
        data = json.loads(session_file.read_text())
        # Reset if new day
        if data.get('date') != str(date.today()):
            data = {'date': str(date.today()), 'spent': 0.0, 'entries': []}
        return data
    return {'date': str(date.today()), 'spent': 0.0, 'entries': []}

def save_session(data):
    ensure_dir()
    (TOKENGUARD_DIR / 'session.json').write_text(json.dumps(data, indent=2))

def cmd_status():
    limit = load_limit()
    session = load_session()
    remaining = limit['limit'] - session['spent']
    print(f"\n🛡️ TokenGuard Status")
    print(f"  Limit:      ${limit['limit']:.2f} {limit['currency']}")
    print(f"  Spent:      ${session['spent']:.2f}")
    print(f"  Remaining:  ${remaining:.2f}")
    pct = session['spent'] / limit['limit'] if limit['limit'] > 0 else 0
    if pct >= 1.0:
        print(f"  ⚠️  BUDGET EXCEEDED! (${session['spent'] - limit['limit']:.2f} over)")
    elif pct >= WARNING_PCT:
        print(f"  ⚠️  WARNING: {pct*100:.0f}% of budget used")
    else:
        print(f"  ✅ Budget OK ({pct*100:.0f}% used)")

def cmd_set(amount):
    amount = float(amount)
    save_limit({'limit': amount, 'currency': 'USD'})
    print(f"✅ Spending limit set to ${amount:.2f} USD")

def cmd_check(cost):
    cost = float(cost)
    limit = load_limit()
    session = load_session()
    if session['spent'] + cost <= limit['limit']:
        print(f"✅ Budget OK: ${cost:.2f} fits (remaining: ${limit['limit'] - session['spent']:.2f})")
        return 0
    else:
        print(f"❌ Budget exceeded: need ${cost:.2f}, only ${limit['limit'] - session['spent']:.2f} remaining")
        return 1

def cmd_log(amount, desc=""):
    amount = float(amount)
    session = load_session()
    session['spent'] += amount
    entry = {
        'timestamp': datetime.now().isoformat(),
        'amount': amount,
        'description': desc or 'API call'
    }
    session['entries'].append(entry)
    save_session(session)
    print(f"✅ Logged ${amount:.2f}: {desc or 'API call'}")
    print(f"   Total spent: ${session['spent']:.2f}")

def cmd_reset():
    save_session({'date': str(date.today()), 'spent': 0.0, 'entries': []})
    print("✅ Session reset")

def cmd_history():
    session = load_session()
    print(f"\n📜 Spending History ({session['date']})")
    print(f"  Total: ${session['spent']:.2f}")
    for entry in session['entries']:
        print(f"  • {entry['timestamp']}: ${entry['amount']:.2f} - {entry['description']}")

def cmd_export(filename):
    limit = load_limit()
    session = load_session()
    data = {
        'exported_at': datetime.now().isoformat(),
        'limit': limit,
        'session': session
    }
    Path(filename).write_text(json.dumps(data, indent=2))
    print(f"✅ Exported to {filename}")

def main():
    if len(sys.argv) < 2:
        print("Usage: tokenguard.py <command> [args]")
        print("Commands: status, set <amt>, check <cost>, log <amt> [desc], reset, history, export <file>")
        return 1

    cmd = sys.argv[1]
    try:
        if cmd == 'status':
            cmd_status()
        elif cmd == 'set':
            cmd_set(sys.argv[2])
        elif cmd == 'check':
            sys.exit(cmd_check(sys.argv[2]))
        elif cmd == 'log':
            cmd_log(sys.argv[2], ' '.join(sys.argv[3:]) if len(sys.argv) > 3 else '')
        elif cmd == 'reset':
            cmd_reset()
        elif cmd == 'history':
            cmd_history()
        elif cmd == 'export':
            cmd_export(sys.argv[2])
        else:
            print(f"Unknown command: {cmd}")
            return 1
    except (IndexError, ValueError) as e:
        print(f"Error: {e}")
        return 1
    return 0

if __name__ == '__main__':
    sys.exit(main())
